// 官方解法：力扣标准答案（guard-loop 双指针）
// 时间 O(n+m)，空间 O(n+m)，全程一个 StringBuilder，零额外字符串对象
// 作者：力扣官方题解 https://leetcode.cn/problems/merge-strings-alternately/solutions/1913930/
class Solution {
    public String mergeAlternately(String word1, String word2) {
        int m = word1.length(), n = word2.length();
        int i = 0, j = 0;

        StringBuilder ans = new StringBuilder();
        while (i < m || j < n) {
            if (i < m) {
                ans.append(word1.charAt(i));
                ++i;
            }
            if (j < n) {
                ans.append(word2.charAt(j));
                ++j;
            }
        }
        return ans.toString();
    }
}

// 你的最优解（推荐写法）：公共段交替 + 尾巴一次追加，全程一个 StringBuilder
// 时间 O(n+m)，空间 O(n+m)
class Solution {
    public String mergeAlternately(String word1, String word2) {
        int n = word1.length(), m = word2.length();
        StringBuilder sb = new StringBuilder(n + m);
        int i = 0;
        // 公共段：两边都还有字符时，交替 append（无需边界判断）
        while (i < n && i < m) {
            sb.append(word1.charAt(i));
            sb.append(word2.charAt(i));
            i++;
        }
        // 谁长就把谁的尾巴接上（最多只会有一个触发）
        if (i < n) sb.append(word1.substring(i));
        if (i < m) sb.append(word2.substring(i));
        return sb.toString();
    }
}

// 我的解法（切尾巴版 · 已修复）：StringBuilder 由主方法创建并传入 merge，
// 公共段 append 完后直接 sb.append(tail)，全程零额外 String 拼接
class Solution {
    public String mergeAlternately(String word1, String word2) {
        int len1 = word1.length(), len2 = word2.length();
        StringBuilder sb = new StringBuilder(len1 + len2);

        if (len1 > len2) {
            merge(sb, word1, word2, len2);
            sb.append(word1.substring(len2));   // word1 的尾巴
        } else if (len2 > len1) {
            merge(sb, word1, word2, len1);
            sb.append(word2.substring(len1));   // word2 的尾巴
        } else {
            merge(sb, word1, word2, len1);
        }
        return sb.toString();
    }

    // 交替 append 两串的公共段 [0, commonLen)，不负责尾巴
    private void merge(StringBuilder sb, String str1, String str2, int commonLen) {
        for (int i = 0; i < commonLen; i++) {
            sb.append(str1.charAt(i));
            sb.append(str2.charAt(i));
        }
    }
}

